window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(150) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(2500); return 'nav ' + name };
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })) };
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(2000); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.selected = (title) => [...document.querySelectorAll('select')].find((x) => x.title === title)?.selectedOptions[0]?.textContent ?? null;
window.cells = (r) => [...r.querySelectorAll('[role=cell],td')].map((c) => c.textContent.trim());
window.rows = (n) => [...document.querySelectorAll('tbody tr,[role=row]')].slice(0, n).map((r) => cells(r).slice(0, 5).join(' | '));
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); if (!input) return 'NO SEARCH'; setInput(input, name); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED ' + name; b.click(); await sleep(3000); return 'opened ' + name };
window.openView = async (name) => { let b = [...document.querySelectorAll('button')].find((x) => x.textContent.includes(name)); if (!b) { const menu = document.querySelector('[title="Saved views"]'); if (!menu) return false; menu.click(); await sleep(600); b = [...document.querySelectorAll('button')].find((x) => x.textContent.includes(name)) } if (!b) return false; b.click(); await sleep(3500); return true };
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.statusLine = () => document.querySelector('[title="See what is loaded"]')?.textContent.trim() ?? null;
window.h1 = () => document.querySelector('main h1')?.textContent.trim() ?? null;
window.switchTo = async (name) => { const t = trigger(); if (!t) return 'NO MENU'; t.focus(); t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); const item = [...document.querySelectorAll('[role=menuitemradio]')].find((x) => x.textContent.startsWith(name)); if (!item) return 'NO ITEM ' + name; item.click(); await until(() => league() === name, 5000); await sleep(3000); return league() };
window.wnbaReads = () => { const t = document.querySelector('main').innerText; return /No WNBA stats yet/.test(t) && !/could not be opened|unknown league|Error/.test(t) && /^(No WNBA stats yet|WNBA files loaded · no tables yet)$/.test(statusLine()) };
window.button = (name, within = document) => [...within.querySelectorAll('button')].find((x) => x.textContent.trim() === name);
window.section = (name) => [...document.querySelectorAll('main section')].find((s) => s.querySelector('h2')?.textContent.trim() === name);
window.reason = () => document.querySelector('main p')?.textContent ?? '';
window.dl = async (league) => (await window.api.leagues.downloads()).leagues.find((d) => d.league === league);
window.roundTrip = async (label, keep) => { const before = keep(); const w = await switchTo('WNBA'); const onW = { league: w, h1: h1(), reads: wnbaReads(), status: statusLine() }; const n = await switchTo('NBA'); const after = keep(); return check(label, w === 'WNBA' && onW.reads && n === 'NBA' && JSON.stringify(after) === JSON.stringify(before), { before, onW, after }) };
